package com.aftersales.copilot.ticket.api;
import com.aftersales.copilot.auth.domain.*; import com.aftersales.copilot.auth.infrastructure.SnowflakeIdGenerator; import com.aftersales.copilot.common.api.ApiResponse; import com.aftersales.copilot.ticket.infrastructure.mapper.TicketMapper; import org.springframework.http.HttpStatus; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@RestController @RequestMapping("/api/v1/admin/warranty-rules") public class WarrantyRuleAdminController { private final TicketMapper mapper; private final SnowflakeIdGenerator ids; public WarrantyRuleAdminController(TicketMapper mapper,SnowflakeIdGenerator ids){this.mapper=mapper;this.ids=ids;} @GetMapping public ApiResponse<?> list(@AuthenticationPrincipal AuthenticatedUser u){check(u);return ApiResponse.success(mapper.listRules(),null);} @PostMapping public ApiResponse<?> create(@AuthenticationPrincipal AuthenticatedUser u,@RequestBody RuleRequest r){check(u);if(r.refundOnlyDays()<0||r.returnRefundDays()<0||r.exchangeDays()<0||r.repairDays()<0)throw new IllegalArgumentException("规则窗口不能为负数");LocalDateTime now=LocalDateTime.now(ZoneOffset.UTC);mapper.insertRule(ids.nextId(),r.ruleCode(),r.name(),r.scopeType(),r.scopeId(),r.refundOnlyDays(),r.returnRefundDays(),r.exchangeDays(),r.repairDays(),r.requiresUnopened(),r.effectiveFrom(),r.effectiveTo(),r.status(),now);return ApiResponse.success(r,null);} @PutMapping("/{id}/status") public ApiResponse<?> status(@AuthenticationPrincipal AuthenticatedUser u,@PathVariable long id,@RequestBody StatusRequest r){check(u);if(mapper.updateRuleStatus(id,r.status(),r.version(),LocalDateTime.now(ZoneOffset.UTC))!=1)throw new IllegalStateException("规则版本冲突");return ApiResponse.success(null,null);} private void check(AuthenticatedUser u){if(u==null||u.role()!=UserRole.ADMIN)throw new com.aftersales.copilot.ticket.domain.TicketException("ADMIN_REQUIRED","仅管理员可管理售后规则",HttpStatus.FORBIDDEN);} public record RuleRequest(String ruleCode,String name,String scopeType,Long scopeId,int refundOnlyDays,int returnRefundDays,int exchangeDays,int repairDays,boolean requiresUnopened,LocalDateTime effectiveFrom,LocalDateTime effectiveTo,String status){} public record StatusRequest(String status,int version){} }
